import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    statistic_trade_by_day_list: [],
    last_information: undefined,
};
export const statisticTradeByDaySlice = createSlice({
    name: 'statisticTradeByDay',
    initialState,
    reducers: {
        setStatisticTradeByDay: (state, action) => {
            state.statistic_trade_by_day_list = action.payload.statistic_trade_by_day_list;
            const lastIdx = action.payload.statistic_trade_by_day_list.length;
            state.last_information = action.payload.statistic_trade_by_day_list[lastIdx - 1];
        },
        resetStatisticTradeByDaySlice() {
            return initialState;
        },
    }
});
export const { actions: statisticTradeByDayActions } = statisticTradeByDaySlice;
export const { reducer: statisticTradeByDayReducer } = statisticTradeByDaySlice;
