import { DEFAULT_THEME } from '06_shared/contexts/ThemeContext';
import { chartChrome, chartSeries } from '06_shared/constants/colors';
import { chartFont } from '06_shared/constants/tokens';
const parseLabel = (context) => {
    const label = context.dataset.label;
    return `${label}: ${context.formattedValue.replace('-', '')} ${context.dataset.postfix}`;
};
const prepareDataAndOptions = (list, roeType = 'line', theme = DEFAULT_THEME, calculateCountBuyCallback, calculateCountSellCallback, calculateRoeCallback, parseCurrentPriceCallback, parseLabelStringCallback) => {
    const { axis: accentColor, grid: noAccentColor, baseline } = chartChrome(theme);
    // Явні властивості, а не spread: так chart.js-датасети лишаються одним
    // нормалізованим типом (тести читають .type з будь-якого з них).
    const series = {
        short: chartSeries(theme, 'short'),
        long: chartSeries(theme, 'long'),
        price: chartSeries(theme, 'price'),
        profit: chartSeries(theme, 'profit'),
        loss: chartSeries(theme, 'loss'),
    };
    const labels = [];
    const current_price_list = [];
    const count_buy_list = [];
    const count_sell_list = [];
    const roe_profit_list = [];
    const roe_loss_list = [];
    let max_count = 0;
    let max_roe = 0;
    const null_list = [];
    const list_length = list.length;
    let roeSign = 0;
    for (let i = 0; i < list_length; i++) {
        labels.push(parseLabelStringCallback(list_length, i));
        current_price_list.push(parseCurrentPriceCallback(list[i]));
        const count_buy = calculateCountBuyCallback(list[i]);
        const count_sell = calculateCountSellCallback(list[i]);
        const roe = calculateRoeCallback(list[i]);
        if (count_buy > max_count) {
            max_count = count_buy;
        }
        if (count_sell > max_count) {
            max_count = count_sell;
        }
        if (Math.abs(roe) > max_roe) {
            max_roe = Math.abs(roe);
        }
        count_buy_list.push(-1 * count_buy);
        count_sell_list.push(-1 * count_sell);
        if (roe > 0) {
            roe_profit_list.push(roe);
            if (roeType === 'line') {
                roe_loss_list.push(roeSign === -1 ? roe : NaN);
            }
            else {
                roe_loss_list.push(NaN);
            }
            roeSign = 1;
        }
        else {
            if (roeType === 'line') {
                roe_profit_list.push(roeSign === 1 ? (-1 * roe) : NaN);
            }
            else {
                roe_profit_list.push(NaN);
            }
            roe_loss_list.push(-1 * roe);
            roeSign = -1;
        }
        null_list.push(0);
    }
    const options = {
        responsive: true,
        maintainAspectRatio: false,
        interaction: {
            mode: 'index',
            intersect: false,
        },
        // У STATIC-збірці анімація вимкнена заради детермінізму візуальних знімків.
        animation: {
            duration: __IS_STATIC__ ? 0 : 250,
            easing: 'easeInOutCubic',
        },
        stacked: false,
        plugins: {
            legend: {
                display: false,
            },
            tooltip: {
                enabled: true,
                titleFont: chartFont('body'),
                bodyFont: chartFont('bodyS'),
                filter: (item) => item.dataset.label,
                callbacks: {
                    label: parseLabel
                }
            },
        },
        scales: {
            x: {
                grid: {
                    display: true,
                    drawOnChartArea: false,
                    drawTicks: false,
                },
                ticks: {
                    color: accentColor,
                    maxTicksLimit: 10,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: accentColor,
                },
            },
            y: {
                type: 'linear',
                display: true,
                position: 'left',
                grid: {
                    drawOnChartArea: false,
                    color: noAccentColor,
                    tickColor: accentColor,
                },
                ticks: {
                    color: accentColor,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: accentColor,
                },
            },
            y1: {
                type: 'linear',
                display: true,
                position: 'right',
                grid: {
                    drawOnChartArea: false,
                    color: noAccentColor,
                    tickColor: accentColor,
                },
                min: -1 * max_count,
                max: max_count,
                ticks: {
                    color: accentColor,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: accentColor,
                },
            },
            y2: {
                type: 'linear',
                display: true,
                position: 'right',
                grid: {
                    drawOnChartArea: false,
                    color: noAccentColor,
                    tickColor: accentColor,
                },
                min: -1 * max_roe,
                max: max_roe,
                ticks: {
                    color: accentColor,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: accentColor,
                },
            },
        },
    };
    const data = {
        labels,
        datasets: [
            {
                label: undefined,
                data: null_list,
                borderColor: baseline,
                yAxisID: 'y1',
                pointRadius: 0,
                tension: 0.04,
                borderWidth: 1,
                postfix: '',
            },
            {
                label: 'Count Sell',
                data: count_sell_list,
                backgroundColor: series.short.backgroundColor,
                borderColor: series.short.borderColor,
                yAxisID: 'y1',
                pointRadius: 0,
                tension: 0.04,
                fill: true,
                borderWidth: 1,
                postfix: '',
            },
            {
                label: 'Count Buy',
                data: count_buy_list,
                backgroundColor: series.long.backgroundColor,
                borderColor: series.long.borderColor,
                yAxisID: 'y1',
                pointRadius: 0,
                tension: 0.04,
                fill: true,
                borderWidth: 1,
                postfix: '',
            },
            {
                label: 'Bitcoin Price',
                data: current_price_list,
                backgroundColor: series.price.backgroundColor,
                borderColor: series.price.borderColor,
                yAxisID: 'y',
                pointRadius: 0,
                tension: 0.04,
                borderWidth: 2,
                postfix: 'USD',
            },
            {
                type: roeType,
                label: 'ROE Profit',
                data: roe_profit_list,
                backgroundColor: series.profit.backgroundColor,
                borderColor: series.profit.borderColor,
                yAxisID: 'y2',
                pointRadius: 0,
                tension: 0.04,
                fill: true,
                borderWidth: 1,
                postfix: '%',
            },
            {
                type: roeType,
                label: 'ROE Loss',
                data: roe_loss_list,
                backgroundColor: series.loss.backgroundColor,
                borderColor: series.loss.borderColor,
                yAxisID: 'y2',
                pointRadius: 0,
                tension: 0.04,
                fill: true,
                borderWidth: 1,
                postfix: '%',
            },
        ],
    };
    return {
        options,
        data
    };
};
export { prepareDataAndOptions };
