import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    statistic_trade_by_month_list: [],
    last_information: undefined,
};
export const statisticTradeByMonthSlice = createSlice({
    name: 'statisticTradeByMonth',
    initialState,
    reducers: {
        setStatisticTradeByMonth: (state, action) => {
            state.statistic_trade_by_month_list = action.payload.statistic_trade_by_month_list;
            const lastIdx = action.payload.statistic_trade_by_month_list.length;
            state.last_information = action.payload.statistic_trade_by_month_list[lastIdx - 1];
        },
        resetStatisticTradeByMonthSlice() {
            return initialState;
        },
    }
});
export const { actions: statisticTradeByMonthActions } = statisticTradeByMonthSlice;
export const { reducer: statisticTradeByMonthReducer } = statisticTradeByMonthSlice;
