const calculateCountBuyForMonth = (item) => {
    return item.trade_close_count_buy;
};
const calculateCountSellForMonth = (item) => {
    return item.trade_close_count_sell;
};
const calculateRoeForMonth = (item) => {
    return item.trade_close_roe_buy + item.trade_close_roe_sell;
};
const parseCurrentPriceForMonth = (item) => {
    return item.current_price;
};
const parseLabelStringForMonth = (list_length, index) => {
    return `${(list_length - index)} Days ago`;
};
export { calculateCountBuyForMonth, calculateCountSellForMonth, calculateRoeForMonth, parseCurrentPriceForMonth, parseLabelStringForMonth, };
