const calculateCountBuyForDay = (item) => {
    return item.trade_open_count_buy;
};
const calculateCountSellForDay = (item) => {
    return item.trade_open_count_sell;
};
const calculateRoeForDay = (item) => {
    return item.trade_open_roe_buy + item.trade_open_roe_sell;
};
const parseCurrentPriceForDay = (item) => {
    return item.current_price;
};
const parseLabelStringForDay = (list_length, index) => {
    return `${(list_length - index) * 5} Minutes ago`;
};
export { calculateCountBuyForDay, calculateCountSellForDay, calculateRoeForDay, parseCurrentPriceForDay, parseLabelStringForDay, };
